    INSERT INTO `obj_stringtranslator` (`obj_uuid`, `created`, `modified`, `label`, `lang`, `langstring`, `active`) VALUES
        ('0fa856ae-674a-4844-83a1-18bb11dba3b0', '2024-11-15 00:00:00', '2024-11-15 00:00:00', "<x id=1> Introducing a new option: AI translate your content and receive quality translation scores, then Verify with Straker to send for human verification.", "fr", "<x id=1> Présentation d'une nouvelle option : l'IA traduit votre contenu et reçoit des notes de qualité de traduction, puis vérifiez avec Straker pour envoyer une vérification humaine.", 1);
    INSERT INTO `obj_stringtranslator` (`obj_uuid`, `created`, `modified`, `label`, `lang`, `langstring`, `active`) VALUES
        ('1de95a62-1793-4f8f-978b-65d33d1c67f6', '2024-11-15 00:00:00', '2024-11-15 00:00:00', "<x id=1> Welcome to the Straker Translate!", "fr", "<x id=1> Bienvenue sur Straker Translate !", 1);
    INSERT INTO `obj_stringtranslator` (`obj_uuid`, `created`, `modified`, `label`, `lang`, `langstring`, `active`) VALUES
        ('8cf18b38-6954-463c-bbb7-7a8b19400319', '2024-11-15 00:00:00', '2024-11-15 00:00:00', "Straker Community is a place for people who use Straker's users to provide feedback, and help each other get the most out of our platform. It's also a place for us to talk about the latest and greatest Verify and Enterprise features, provide updates, and engage with customers like you!", "fr", "La communauté Straker est un endroit où les utilisateurs de Straker peuvent donner leur avis et s'entraider pour tirer le meilleur parti de notre plateforme. C'est aussi un endroit où nous pouvons parler des dernières et meilleures fonctionnalités de Verify et d'Enterprise, fournir des mises à jour et échanger avec des clients comme vous !", 1);
    INSERT INTO `obj_stringtranslator` (`obj_uuid`, `created`, `modified`, `label`, `lang`, `langstring`, `active`) VALUES
        ('1e1555f6-bf35-4c48-a1e3-ff5cd3efd91a', '2024-11-15 00:00:00', '2024-11-15 00:00:00', "AI translate your content and receive quality translation scores, then Verify with Straker to send for human verification.", "fr", "Traduisez votre contenu par IA et recevez des scores de traduction de qualité, puis vérifiez avec Straker pour envoyer une vérification humaine.", 1);
    INSERT INTO `obj_stringtranslator` (`obj_uuid`, `created`, `modified`, `label`, `lang`, `langstring`, `active`) VALUES
        ('6ff19969-2196-4171-a313-3a7b0ddbf96c', '2024-11-15 00:00:00', '2024-11-15 00:00:00', "Create a name for your project", "fr", "Créez un nom pour votre projet", 1);
    INSERT INTO `obj_stringtranslator` (`obj_uuid`, `created`, `modified`, `label`, `lang`, `langstring`, `active`) VALUES
