    INSERT INTO `obj_stringtranslator` (`obj_uuid`, `created`, `modified`, `label`, `lang`, `langstring`, `active`) VALUES
        ('a0d2cc1c-e0bc-48fa-a1c8-9a8c04721d8b', '2024-11-15 00:00:00', '2024-11-15 00:00:00', "Which language(s) do you want the file to be translated to?", "fr", "Dans quelle(s) langue(s) voulez-vous que le fichier soit traduit ?", 1);
