    INSERT INTO `obj_stringtranslator` (`obj_uuid`, `created`, `modified`, `label`, `lang`, `langstring`, `active`) VALUES
        ('f0f50385-65ca-40d1-a0a8-0b6283554e8c', '2024-11-15 00:00:00', '2024-11-15 00:00:00', "<x id=1> Introducing a new option: AI translate your content and receive quality translation scores, then Verify with Straker to send for human verification.", "de", "<x id=1> Wir haben eine neue Funktion eingeführt: Lassen Sie Ihre Texte von einer KI übersetzen und erhalten Sie eine Punktzahl für die Qualität der Übersetzung. Verwenden Sie anschließend Verify von Straker, um die Texte an einen menschlichen Prüfer zu senden.", 1);
    INSERT INTO `obj_stringtranslator` (`obj_uuid`, `created`, `modified`, `label`, `lang`, `langstring`, `active`) VALUES
        ('2a5d57ed-e56e-4daa-9009-5fa1cb252127', '2024-11-15 00:00:00', '2024-11-15 00:00:00', "<x id=1> Welcome to the Straker Translate!", "de", "<x id=1> Willkommen bei Straker Translate!", 1);
    INSERT INTO `obj_stringtranslator` (`obj_uuid`, `created`, `modified`, `label`, `lang`, `langstring`, `active`) VALUES
        ('80464bf7-daa1-49e3-a3e4-4787ed33d950', '2024-11-15 00:00:00', '2024-11-15 00:00:00', "Straker Community is a place for people who use Straker's users to provide feedback, and help each other get the most out of our platform. It's also a place for us to talk about the latest and greatest Verify and Enterprise features, provide updates, and engage with customers like you!", "de", "Die Straker Community ist ein Ort, an dem Benutzer der Straker-Plattform Feedback geben und sich gegenseitig helfen können, das Beste aus unserer Plattform herauszuholen. Sie ist auch ein Ort, an dem wir über die neuesten und besten Verify- und Enterprise-Funktionen sprechen, Updates bereitstellen und mit Kunden wie Ihnen in Kontakt treten können!", 1);
    INSERT INTO `obj_stringtranslator` (`obj_uuid`, `created`, `modified`, `label`, `lang`, `langstring`, `active`) VALUES
        ('8e49cc37-fca5-432c-91e9-84debc21de8e', '2024-11-15 00:00:00', '2024-11-15 00:00:00', "AI translate your content and receive quality translation scores, then Verify with Straker to send for human verification.", "de", "Lassen Sie Ihre Texte von einer KI übersetzen und erhalten Sie eine Punktzahl für die Qualität der Übersetzung. Verwenden Sie anschließend Verify von Straker, um die Texte an einen menschlichen Prüfer zu senden.", 1);
    INSERT INTO `obj_stringtranslator` (`obj_uuid`, `created`, `modified`, `label`, `lang`, `langstring`, `active`) VALUES
