    INSERT INTO `obj_stringtranslator` (`obj_uuid`, `created`, `modified`, `label`, `lang`, `langstring`, `active`) VALUES
        ('ccfe8993-2023-4096-b375-a46fe84a5047', '2024-11-15 00:00:00', '2024-11-15 00:00:00', "<x id=1> Introducing a new option: AI translate your content and receive quality translation scores, then Verify with Straker to send for human verification.", "es", "<x id=1> Introducimos una nueva opción: traduce tus contenidos con IA y obtén valoraciones de la calidad de la traducción y, a continuación, envíalos para su verificación con ayuda de un experto humano con la herramienta Verify de Straker.", 1);
    INSERT INTO `obj_stringtranslator` (`obj_uuid`, `created`, `modified`, `label`, `lang`, `langstring`, `active`) VALUES
        ('1d16024a-68f5-4f7b-9750-445d4a4a8ce5', '2024-11-15 00:00:00', '2024-11-15 00:00:00', "<x id=1> Welcome to the Straker Translate!", "es", "<x id=1> ¡Te damos la bienvenida a Straker Translate!", 1);
    INSERT INTO `obj_stringtranslator` (`obj_uuid`, `created`, `modified`, `label`, `lang`, `langstring`, `active`) VALUES
        ('d5c58e6b-9064-4f60-b86e-f5bb5a15fcc5', '2024-11-15 00:00:00', '2024-11-15 00:00:00', "Straker Community is a place for people who use Straker's users to provide feedback, and help each other get the most out of our platform. It's also a place for us to talk about the latest and greatest Verify and Enterprise features, provide updates, and engage with customers like you!", "es", "La Straker Community es un lugar para que nuestros usuarios compartan su opinión y se ayuden mutuamente a sacar el máximo provecho de nuestra plataforma. También es un lugar idóneo para hablar sobre las últimas y destacadas funciones de Verify y Enterprise, ofrecer actualizaciones e interactuar con clientes como tú.", 1);
    INSERT INTO `obj_stringtranslator` (`obj_uuid`, `created`, `modified`, `label`, `lang`, `langstring`, `active`) VALUES
        ('5bb5e831-a8e5-4af2-864a-749d30068e43', '2024-11-15 00:00:00', '2024-11-15 00:00:00', "AI translate your content and receive quality translation scores, then Verify with Straker to send for human verification.", "es", "Traduce tu contenido con IA y obtén una valoración sobre la calidad de la traducción: después, utiliza la función Verify de Straker para enviar los archivos a un experto para su verificación.", 1);
    INSERT INTO `obj_stringtranslator` (`obj_uuid`, `created`, `modified`, `label`, `lang`, `langstring`, `active`) VALUES
