    INSERT INTO `obj_stringtranslator` (`obj_uuid`, `created`, `modified`, `label`, `lang`, `langstring`, `active`) VALUES
        ('3436f4a3-e2c4-4c36-a49b-e102855c598c', '2024-11-15 00:00:00', '2024-11-15 00:00:00', "Which language(s) do you want the file to be translated to?", "es", "¿A qué idioma(s) deseas traducir el archivo?", 1);
    INSERT INTO `obj_stringtranslator` (`obj_uuid`, `created`, `modified`, `label`, `lang`, `langstring`, `active`) VALUES
