    INSERT INTO `obj_stringtranslator` (`obj_uuid`, `created`, `modified`, `label`, `lang`, `langstring`, `active`) VALUES
        ('14e8c940-79d2-4bf1-9954-3db2e71b1975', '2024-11-15 00:00:00', '2024-11-15 00:00:00', "This video cannot be sent for transcription as it doesn't have any sound", "jp", "この動画は音声が入っていないため、文字起こしを依頼することができません。", 1);
    INSERT INTO `obj_stringtranslator` (`obj_uuid`, `created`, `modified`, `label`, `lang`, `langstring`, `active`) VALUES
        ('083d9616-5082-4b6e-b96d-42490caf8ef2', '2024-11-15 00:00:00', '2024-11-15 00:00:00', "Thank you for sending your document for human verification! We will notify as soon as the translation is complete.", "jp", "翻訳者による検証のための文書をご送付いただきありがとうございます。翻訳が完成次第ご連絡いたします。", 1);
    INSERT INTO `obj_stringtranslator` (`obj_uuid`, `created`, `modified`, `label`, `lang`, `langstring`, `active`) VALUES
        ('a839ebb7-e936-4c3a-9571-86bcf682c3b9', '2024-11-15 00:00:00', '2024-11-15 00:00:00', "Please select at least one language for verification.", "jp", "検証を依頼するためには、少なくとも1つの言語を選択してください。", 1);
    INSERT INTO `obj_stringtranslator` (`obj_uuid`, `created`, `modified`, `label`, `lang`, `langstring`, `active`) VALUES
