    INSERT INTO `obj_stringtranslator` (`obj_uuid`, `created`, `modified`, `label`, `lang`, `langstring`, `active`) VALUES
        ('229f4232-2918-4d14-bab3-3a8a9e9eea67', '2024-11-15 00:00:00', '2024-11-15 00:00:00', "Please select a language to translate to.", "jp", "翻訳後の言語を選択してください。", 1);
    INSERT INTO `obj_stringtranslator` (`obj_uuid`, `created`, `modified`, `label`, `lang`, `langstring`, `active`) VALUES
