    INSERT INTO `obj_stringtranslator` (`obj_uuid`, `created`, `modified`, `label`, `lang`, `langstring`, `active`) VALUES
        ('4c107705-e11d-467e-810e-12fd96d2859a', '2024-11-15 00:00:00', '2024-11-15 00:00:00', "<x id=1> Introducing a new option: AI translate your content and receive quality translation scores, then Verify with Straker to send for human verification.", "jp", "<x id=1> 新しいオプションの導入： お客様のファイルをAIが翻訳し、AI翻訳の品質の採点結果を見ることができます。その後、必要に応じてStrakerのサービスを利用して翻訳者による検証を依頼することができます。", 1);
    INSERT INTO `obj_stringtranslator` (`obj_uuid`, `created`, `modified`, `label`, `lang`, `langstring`, `active`) VALUES
        ('5c3febc0-d0f9-4e1c-b403-4e2e655d3f97', '2024-11-15 00:00:00', '2024-11-15 00:00:00', "<x id=1> Welcome to the Straker Translate!", "jp", "<x id=1> Straker Translateへようこそ。", 1);
    INSERT INTO `obj_stringtranslator` (`obj_uuid`, `created`, `modified`, `label`, `lang`, `langstring`, `active`) VALUES
        ('813e273f-b432-4344-affb-d78a9fb59512', '2024-11-15 00:00:00', '2024-11-15 00:00:00', "Straker Community is a place for people who use Straker's users to provide feedback, and help each other get the most out of our platform. It's also a place for us to talk about the latest and greatest Verify and Enterprise features, provide updates, and engage with customers like you!", "jp", "Straker Communityは、Strakerアプリをご利用いただいているお客様がフィードバックを行う場で、当社のプラットフォームを最大限に活用できるように、お客様と当社が互いにサポートし合える場になります。また、当社のVerifyやEnterpriseの最新の機能や更新情報などをご紹介する場でもあり、当社がお客様とつながる場でもあります。", 1);
    INSERT INTO `obj_stringtranslator` (`obj_uuid`, `created`, `modified`, `label`, `lang`, `langstring`, `active`) VALUES
        ('2877a497-c8ce-4b36-b1e0-992fb7f81efa', '2024-11-15 00:00:00', '2024-11-15 00:00:00', "AI translate your content and receive quality translation scores, then Verify with Straker to send for human verification.", "jp", "お客様のファイルをAIが翻訳し、AI翻訳の品質の採点結果を見ることができます。その後、必要に応じてStrakerのサービスを利用して翻訳者による検証を依頼することができます。", 1);
    INSERT INTO `obj_stringtranslator` (`obj_uuid`, `created`, `modified`, `label`, `lang`, `langstring`, `active`) VALUES
