    INSERT INTO `obj_stringtranslator` (`obj_uuid`, `created`, `modified`, `label`, `lang`, `langstring`, `active`) VALUES
        ('d291acca-32ee-49b4-a438-927d894b57ef', '2024-11-15 00:00:00', '2024-11-15 00:00:00', "<x id=1> Welcome to the Straker Translate!", "fr-ca", "<x id=1> Bienvenue sur le site Straker Translate!", 1);
    INSERT INTO `obj_stringtranslator` (`obj_uuid`, `created`, `modified`, `label`, `lang`, `langstring`, `active`) VALUES
        ('f03f1e8a-cf09-4d7c-aeb2-56cbc79669e2', '2024-11-15 00:00:00', '2024-11-15 00:00:00', "Straker Community is a place for people who use Straker's users to provide feedback, and help each other get the most out of our platform. It's also a place for us to talk about the latest and greatest Verify and Enterprise features, provide updates, and engage with customers like you!", "fr-ca", "La communauté Straker est un lieu où les utilisateurs de Straker peuvent faire part de leurs commentaires et s'aider mutuellement à tirer le meilleur parti de notre plateforme. C'est aussi un endroit où nous pouvons parler des dernières et meilleures fonctionnalités de Verify et Enterprise, fournir des mises à jour et échanger avec des clients comme vous!", 1);
    INSERT INTO `obj_stringtranslator` (`obj_uuid`, `created`, `modified`, `label`, `lang`, `langstring`, `active`) VALUES
